// PRIVATE redacted companion evidence. Hashes bind bytes, never authenticate a
// provider, reproduce original owner capabilities, or authorize replay.
import {types} from 'node:util';
import {stableStringify,sha256Text,cloneFreeze,RUN_OUTCOMES} from '../workflow/contracts.mjs';
import {record as readExact} from '../evaluation/intake-v1.mjs';
import {decideExecutionAdmission} from '../hosts/repository/execution-admission-v1.mjs';

export const SIDECAR_LIMITS=Object.freeze({maxRecords:4096,maxRecordBytes:1048576,maxBytes:16777216});
const fail=()=>{throw Object.assign(Error('ARM_SIDECAR_INVALID'),{code:'ARM_SIDECAR_INVALID'});};
const check=ok=>{if(!ok)fail();};
const exact=(value,keys)=>{try{return readExact(value,keys);}catch{fail();}};
const digest=x=>check(typeof x==='string'&&/^[a-f0-9]{64}$/u.test(x));
const natural=x=>check(Number.isSafeInteger(x)&&x>=0&&!Object.is(x,-0));
const uuid=x=>check(typeof x==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/u.test(x));
const code=x=>check(x===null||typeof x==='string'&&/^[A-Z][A-Z0-9_]{0,95}$/u.test(x));
const pick=(x,keys)=>Object.fromEntries(keys.map(k=>[k,x[k]]));
export const armSidecarDigestV1=value=>sha256Text('nisi/paired-arm-data/v1\0'+stableStringify(bounded(value)));
const equal=(a,b)=>stableStringify(a)===stableStringify(b);
const phases=['EXECUTOR','ORACLE'];

// Snapshot before reflection or serialization; reject accessors, proxies, cycles,
// unsupported scalars and hidden data. No truncation or implicit toJSON calls.
function bounded(value,depth=0,seen=new WeakSet(),budget={nodes:0,bytes:0}){
  check(++budget.nodes<=8192&&depth<=16);
  if(typeof value==='string'){
    check(value.isWellFormed()&&value.length<=4096);budget.bytes+=Buffer.byteLength(value);check(budget.bytes<=524288);return value;
  }
  if(value===null||typeof value==='boolean')return value;
  if(typeof value==='number'){check(Number.isFinite(value)&&!Object.is(value,-0));return value;}
  check(value&&typeof value==='object'&&!types.isProxy(value)&&!seen.has(value));seen.add(value);
  const keys=Reflect.ownKeys(value);check(keys.length<=257);
  let out;
  if(Array.isArray(value)){
    const length=Object.getOwnPropertyDescriptor(value,'length')?.value;
    check(Number.isSafeInteger(length)&&length<=256&&keys.length===length+1);
    out=[];for(let i=0;i<length;i++){
      const d=Object.getOwnPropertyDescriptor(value,String(i));check(d?.enumerable&&Object.hasOwn(d,'value'));
      Object.defineProperty(out,i,{value:bounded(d.value,depth+1,seen,budget),enumerable:true,writable:true,configurable:true});
    }
  }else{
    check([Object.prototype,null].includes(Object.getPrototypeOf(value)));out=Object.create(null);
    for(const k of keys){
      check(typeof k==='string'&&k.length<=96&&!['candidateText','prompt','messages','sourceCode','apiKey'].includes(k));
      const d=Object.getOwnPropertyDescriptor(value,k);check(d?.enumerable&&Object.hasOwn(d,'value'));
      Object.defineProperty(out,k,{value:bounded(d.value,depth+1,seen,budget),enumerable:true,writable:true,configurable:true});
    }
  }
  seen.delete(value);return out;
}
function reference(value){const r=exact(value,['sequence','sha256']);natural(r.sequence);digest(r.sha256);}
function approval(value){
  const a=exact(value,['id','ownerId','planSha256','profileSha256','expiresAtMs','priority']);
  for(const k of ['id','ownerId'])check(typeof a[k]==='string'&&/^[a-z][a-z0-9_.-]{0,95}$/u.test(a[k]));
  digest(a.planSha256);digest(a.profileSha256);natural(a.expiresAtMs);check(a.expiresAtMs>0&&['FOREGROUND','BACKGROUND'].includes(a.priority));
}
function observation(value,at,approved,decision){
  natural(at);approval(approved);
  const o=exact(value,['consent','scheduler','capacity','host','custody']);
  const c=exact(o.consent,['id','ownerId','planSha256','profileSha256','grantedAtMs','expiresAtMs','revoked','scope']);
  for(const key of ['id','ownerId','planSha256','profileSha256'])check(c[key]===approved[key]);
  natural(c.grantedAtMs);natural(c.expiresAtMs);check(c.grantedAtMs<=at&&at<c.expiresAtMs&&at<approved.expiresAtMs);
  const s=exact(o.scheduler,['decision','observedAtMs','freshnessMs','queueState']);
  const m=exact(o.capacity,['configuredSlots','measuredFreeSlots','measuredAtMs','freshnessMs']);
  const h=exact(o.host,['state','pendingTransports','observedAtMs']);
  const custody=exact(o.custody,['taskSha256','baselineSha256','oracleSha256','suiteFingerprint',
    'reviewedSourceFingerprint','toolchainSha256','resourceBudgetSha256','observedAtMs','freshnessMs']);
  for(const [key,v] of Object.entries(custody))if(!['observedAtMs','freshnessMs'].includes(key))digest(v);
  for(const [time,span] of [[s.observedAtMs,s.freshnessMs],[m.measuredAtMs,m.freshnessMs],[h.observedAtMs,5000],[custody.observedAtMs,custody.freshnessMs]]){
    natural(time);natural(span);check(span>0&&span<=5000&&time<=at&&at-time<span);
  }
  const expected=decideExecutionAdmission({now:at,consent:pick(c,['grantedAtMs','expiresAtMs','revoked','scope']),
    scheduler:s,capacity:m,host:h,request:pick(approved,['priority','ownerId'])});
  check(expected.status==='ADMIT'&&equal(expected,decision));
}
function projection(p){
  exact(p,['fingerprint','intentSha256','inputsSha256','repositoryRunId','reportSha256','repositoryReceiptFingerprint','repositoryReceiptStatus',
    'engineOutcome','workflowOutcome','completionClaim','candidate','treatment','usage']);
  for(const k of ['fingerprint','intentSha256','inputsSha256','reportSha256','repositoryReceiptFingerprint'])digest(p[k]);uuid(p.repositoryRunId);
  check(['INCOMPLETE','CONSISTENT_NO_PROGRESS','SCOPED_LIVE_REPAIR_REVIEW_PASS','SYNTHETIC_CONTRACT_PASS'].includes(p.repositoryReceiptStatus));
  check(RUN_OUTCOMES.includes(p.engineOutcome)&&RUN_OUTCOMES.includes(p.workflowOutcome));
  check(typeof p.completionClaim==='boolean'&&p.completionClaim===(p.engineOutcome==='COMPLETED'));
  const c=exact(p.candidate,['serializationProfile','candidateFingerprint','candidateSha256','byteLength']);
  check(c.serializationProfile==='nisi-workflow-stable-json-v1');digest(c.candidateFingerprint);digest(c.candidateSha256);natural(c.byteLength);check(c.byteLength<=1048576);
  const t=exact(p.treatment,['arm','treatmentFingerprint','policySha256','applicationPoint','requestInspection',
    'localDispatch','systemPromptSha256','modelUseAttested','effectiveness']);
  check(['OFF','ON'].includes(t.arm));digest(t.treatmentFingerprint);digest(t.policySha256);
  for(const k of ['applicationPoint','requestInspection','localDispatch'])check(typeof t[k]==='string'&&t[k].length>0);
  if(t.systemPromptSha256!==null)digest(t.systemPromptSha256);check(t.modelUseAttested===false&&t.effectiveness==='NOT_MEASURED');
  const u=exact(p.usage,['sourceKind','projectedTokens','projectedModelCalls','durationMs','durationSource']);
  check(['SYNTHETIC_FIXTURE','VALIDATED_REPORTED_COUNTERS'].includes(u.sourceKind)&&u.durationMs===null&&u.durationSource==='NOT_MEASURED');
  if(u.projectedTokens!==null){exact(u.projectedTokens,['input','output']);natural(u.projectedTokens.input);natural(u.projectedTokens.output);}
  if(u.projectedModelCalls!==null)natural(u.projectedModelCalls);
  if(u.sourceKind==='SYNTHETIC_FIXTURE')check(u.projectedTokens===null&&u.projectedModelCalls===null);
}
const shapes={
  HEADER:['runnerId','planSha256','profileSha256','intentsSha256'],
  PREPARED:['requestId','ownerSetId','phase','intentSha256','producerFingerprint','approval','inputsSha256','observedAtMs','observation','decision'],
  HISTORY:['requestId','ownerSetId','intentSha256','producerFingerprint','disposition','state','failure','entries','approval'],
  START_LINKED:['requestId','ownerSetId','phase','preparedSha256'],
  PHASE_OBSERVED:['requestId','ownerSetId','phase','startSha256','historySha256','projection'],
  FINAL:['rows','failure'],
};
export function readArmSidecarRecordV1(raw){
  const x=bounded(raw);check(typeof x?.kind==='string'&&Object.hasOwn(shapes,x.kind));
  exact(x,['kind','main',...shapes[x.kind]]);reference(x.main);
  if(x.kind==='HEADER'){
    check(x.main.sequence===0);uuid(x.runnerId);for(const k of ['planSha256','profileSha256','intentsSha256'])digest(x[k]);
  }else if(x.kind==='FINAL'){
    code(x.failure);check(Array.isArray(x.rows)&&x.rows.length>0&&x.rows.length<=256);const ids=new Set();
    for(const row of x.rows){exact(row,['requestId','state']);digest(row.requestId);check(!ids.has(row.requestId));ids.add(row.requestId);
      check(['NOT_STARTED','PREPARED_UNCONFIRMED','STARTED_INCOMPLETE','EXECUTOR_OBSERVED','COMPLETE'].includes(row.state));}
  }else{
    digest(x.requestId);uuid(x.ownerSetId);if(Object.hasOwn(x,'phase'))check(phases.includes(x.phase));
    for(const k of ['intentSha256','producerFingerprint','inputsSha256','preparedSha256','startSha256','historySha256'])if(Object.hasOwn(x,k))digest(x[k]);
    if(x.kind==='PREPARED')observation(x.observation,x.observedAtMs,x.approval,x.decision);
    if(x.kind==='HISTORY'){
      approval(x.approval);code(x.state);code(x.failure);
      check(['POST_PHASE_LOCAL_OBSERVATIONS','FINAL_LOCAL_OBSERVATIONS'].includes(x.disposition));
      check(Array.isArray(x.entries)&&x.entries.length>0&&x.entries.length<=4);
      for(const row of x.entries){exact(row,['phase','point','generation','observation','decision','observedAtMs']);
        check(phases.includes(row.phase)&&['PERMIT_MINTED','CONSUMPTION_RECHECK_PASSED'].includes(row.point));natural(row.generation);
        observation(row.observation,row.observedAtMs,x.approval,row.decision);}
    }
    if(x.kind==='PHASE_OBSERVED'){if(x.phase==='EXECUTOR')projection(x.projection);else check(x.projection===null);}
  }
  return cloneFreeze(x);
}
export function encodeArmSidecarRecordV1(raw,ordinal,previousSha256){
  const record=readArmSidecarRecordV1(raw);natural(ordinal);check(ordinal<SIDECAR_LIMITS.maxRecords);
  if(ordinal===0)check(previousSha256===null&&record.kind==='HEADER');else {digest(previousSha256);check(record.kind!=='HEADER');}
  const body={schemaVersion:'nisi-paired-arm-sidecar-chain-v1',ordinal,previousSha256,record,
    authorizing:false,resumable:false,actualDispatchCount:null};
  const sha256=sha256Text('nisi/paired-arm-sidecar-chain/v1\0'+stableStringify(body));
  const bytes=Buffer.from(stableStringify({...body,sha256})+'\n');check(bytes.length<=SIDECAR_LIMITS.maxRecordBytes);
  return {record,sha256,bytes};
}
export function decodeArmSidecarRecordV1(bytes,ordinal,previousSha256){
  check(Buffer.isBuffer(bytes)&&bytes.length<=SIDECAR_LIMITS.maxRecordBytes&&Buffer.from(bytes.toString('utf8')).equals(bytes));
  let parsed;try{parsed=JSON.parse(bytes.toString('utf8'));}catch{fail();}
  const x=exact(parsed,['schemaVersion','ordinal','previousSha256','record','authorizing','resumable','actualDispatchCount','sha256']);
  const expected=encodeArmSidecarRecordV1(x.record,ordinal,previousSha256);check(expected.bytes.equals(bytes));return expected;
}

// Original producer fingerprint is checked BEFORE redaction. The retained
// fingerprint is a reference to discarded raw metadata, not reopened authority.
const producerFlags=['sourceTrust','actualDispatchCount','resumable','authorizing',
  'executionAttested','measurementVerified','publicationAuthorized','fingerprint'];
const producerShapes={
  'nisi-scheduled-arm-admission-v1':['schemaVersion','disposition','ownerSetId','phase','intent',
    'inputs','approval','observation','decision','observedAtMs','ownerKinds',...producerFlags],
  'nisi-scheduled-arm-admission-history-v1':['schemaVersion','disposition','ownerSetId','intent',
    'history','state','failure',...producerFlags],
  'nisi-repository-trial-projection-v2':['schemaVersion','intent','inputs','repositoryRunId',
    'reportSha256','repositoryReceiptFingerprint','repositoryReceiptStatus','repositoryReceiptReasons',
    'engineOutcome','workflowOutcome','completionClaim','completionClaimSource','candidate','treatment',
    'usage','oracleEvaluated','modelAuthenticityAttested','executionAttested','measurementVerified',
    'causalClaim','authorizing','promotionEligible','resumable','fingerprint'],
};
function producer(raw,domain,schema){
  const x=exact(bounded(raw),producerShapes[schema]);check(x.schemaVersion===schema);digest(x.fingerprint);
  const {fingerprint,...body}=x;check(fingerprint===sha256Text(domain+'\0'+stableStringify(body)));
  for(const key of ['authorizing','resumable','executionAttested','measurementVerified'])check(x[key]===false);
  return x;
}
export function projectArmAdmissionV1(raw,main,approved=null){
  const history=raw!==null&&typeof raw==='object'&&!types.isProxy(raw)
    &&Object.getOwnPropertyDescriptor(raw,'schemaVersion')?.value==='nisi-scheduled-arm-admission-history-v1';
  const x=producer(raw,'nisi/scheduled-arm-admission/v1',history?'nisi-scheduled-arm-admission-history-v1':'nisi-scheduled-arm-admission-v1');
  check(x.publicationAuthorized===false&&x.actualDispatchCount===null&&x.sourceTrust==='TRUSTED_HOST_OBSERVATIONS_NOT_ATTESTED');
  if(!history)check(x.disposition==='PRE_DISPATCH_INTENT_ONLY'&&equal(x.ownerKinds,
    ['host','staticChecks','tests','lane','model.author','model.reviewer','oracle']));
  const common={main,requestId:x.intent.requestId,ownerSetId:x.ownerSetId,intentSha256:armSidecarDigestV1(x.intent),producerFingerprint:x.fingerprint};
  return readArmSidecarRecordV1(history?{kind:'HISTORY',...common,disposition:x.disposition,state:x.state,failure:x.failure,entries:x.history,approval:approved}
    :{kind:'PREPARED',...common,phase:x.phase,approval:x.approval,inputsSha256:armSidecarDigestV1(x.inputs),
      observedAtMs:x.observedAtMs,observation:x.observation,decision:x.decision});
}
export function projectArmProjectionV1(raw){
  const x=producer(raw,'nisi/repository-trial-projection/v2','nisi-repository-trial-projection-v2');
  for(const key of ['oracleEvaluated','modelAuthenticityAttested','causalClaim','promotionEligible'])check(x[key]===false);
  check(x.completionClaimSource==='ENGINE_OUTCOME_LABEL_COMPLETED_V1');
  const out={intentSha256:armSidecarDigestV1(x.intent),inputsSha256:armSidecarDigestV1(x.inputs),
    ...pick(x,['fingerprint','repositoryRunId','reportSha256','repositoryReceiptFingerprint','repositoryReceiptStatus',
    'engineOutcome','workflowOutcome','completionClaim','candidate','treatment']),
    usage:pick(x.usage,['sourceKind','projectedTokens','projectedModelCalls','durationMs','durationSource'])};
  projection(out);return cloneFreeze(out);
}

// PRIVATE append-only evidence. The codec owns record validation and chain bytes;
// this module owns bounded local-file admission, acknowledgement, and read-only
// reconciliation. It does not authorize, replay, resume, or authenticate data.
import fs from 'node:fs';
import path from 'node:path';
import { record } from '../evaluation/intake-v1.mjs';
import { cloneFreeze } from '../workflow/contracts.mjs';
import { resolveExternalDemoStateV1, recheckExternalDemoStateV1 } from '../hosts/repository/demo-state-v1.mjs';
import { SIDECAR_LIMITS, encodeArmSidecarRecordV1, decodeArmSidecarRecordV1 } from './paired-arm-sidecar-codec-v1.mjs';

const SOURCE_ROOT = path.resolve(import.meta.dirname, '..');
const NAME = 'arm-sidecar.jsonl';
const noFollow = fs.constants.O_NOFOLLOW;
const ioKeys = ['openSync', 'closeSync', 'writeSync', 'readSync', 'fstatSync', 'fsyncSync'];
const fail = code => { throw Object.assign(Error(code), { code }); };
const identity = stat => ({
  dev: String(stat.dev), ino: String(stat.ino), mode: stat.mode, nlink: stat.nlink,
  uid: typeof stat.uid === 'number' ? stat.uid : null,
});
const sameIdentity = (a, b) => a.dev === String(b.dev) && a.ino === String(b.ino) &&
  a.mode === b.mode && a.nlink === b.nlink && a.uid === (typeof b.uid === 'number' ? b.uid : null);
const currentUid = () => typeof process.getuid === 'function' ? process.getuid() : null;

function ioMethods(dependencies) {
  const { io } = record(dependencies, ['io']);
  return Object.fromEntries(ioKeys.map(key => {
    const fn = Object.getOwnPropertyDescriptor(io, key)?.value;
    if (typeof fn !== 'function') fail('SIDECAR_IO');
    return [key, fn.bind(io)];
  }));
}

function checkPrivateDirectory(observation) {
  const stat = fs.lstatSync(observation.directory);
  const uid = currentUid();
  if (!stat.isDirectory() || stat.isSymbolicLink() || (stat.mode & 0o077) ||
      (uid !== null && stat.uid !== uid) ||
      String(stat.dev) !== observation.dev ||
      String(stat.ino) !== observation.ino) fail('SIDECAR_DIRECTORY_CHANGED');
}

function checkNamedOpened(io, fd, file, fileIdentity, expectedSize) {
  const named = fs.lstatSync(file);
  const opened = io.fstatSync(fd);
  const uid = currentUid();
  for (const stat of [named, opened]) {
    if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1 ||
        (stat.mode & 0o077) || (uid !== null && stat.uid !== uid)) fail('SIDECAR_FILE_CHANGED');
  }
  if (!sameIdentity(fileIdentity, named) || !sameIdentity(fileIdentity, opened) ||
      named.size !== expectedSize || opened.size !== expectedSize) fail('SIDECAR_FILE_CHANGED');
  return { named, opened };
}

function fsyncDirectory(io, directory) {
  const dirFd = io.openSync(directory, fs.constants.O_RDONLY | noFollow | fs.constants.O_DIRECTORY);
  try { io.fsyncSync(dirFd); } finally { io.closeSync(dirFd); }
}

function readExact(io, fd, size, start = 0) {
  if (!Number.isSafeInteger(size) || size < 0 || size > SIDECAR_LIMITS.maxBytes) fail('SIDECAR_READ');
  const bytes = Buffer.alloc(size);
  let offset = 0;
  while (offset < bytes.length) {
    const count = io.readSync(fd, bytes, offset, bytes.length - offset, start + offset);
    if (!Number.isSafeInteger(count) || count <= 0 || count > bytes.length - offset) fail('SIDECAR_EOF');
    offset += count;
  }
  const end = io.readSync(fd, Buffer.alloc(1), 0, 1, start + size);
  if (end !== 0) fail('SIDECAR_EOF');
  return bytes;
}

function snapshot(state) {
  return cloneFreeze({
    schemaVersion: 'nisi-paired-arm-sidecar-store-v1', file: state.file, state: state.state,
    reason: state.reason, failureCause: state.failureCause, retainedRecords: state.ordinal,
    byteLength: state.byteLength, lastSha256: state.previousSha256, finalSeen: state.finalSeen,
    retentionCountSemantics: 'FULLY_CONFIRMED_STORE_OPERATIONS',
    durability: 'OS_FSYNC_ACKNOWLEDGEMENT_ONLY', powerLossVerified: false,
    hostileWriterIsolation: false, authorizing: false, resumable: false,
  });
}

export function createPairedArmSidecarStoreV1(input, dependencies = { io: fs }) {
  const { directory } = record(input, ['directory']);
  const parent = resolveExternalDemoStateV1(directory, SOURCE_ROOT);
  const io = ioMethods(dependencies);
  recheckExternalDemoStateV1(parent, SOURCE_ROOT);
  const file = path.join(parent.directory, NAME);
  let fd = null, fileIdentity = null, state = 'OPEN', busy = false;
  let ordinal = 0, byteLength = 0, previousSha256 = null, finalSeen = false;
  let reason = null, failureCause = null;
  const closeOwned = cause => {
    if (fd === null) return;
    const owned = fd; fd = null;
    try { io.closeSync(owned); } catch {
      failureCause ??= cause;
      state = 'COMMIT_UNCERTAIN'; reason = cause;
    }
  };
  const verify = () => {
    recheckExternalDemoStateV1(parent, SOURCE_ROOT);
    checkPrivateDirectory(parent);
    checkNamedOpened(io, fd, file, fileIdentity, byteLength);
  };
  try {
    fd = io.openSync(file, fs.constants.O_RDWR | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_APPEND | noFollow, 0o600);
    fileIdentity = identity(io.fstatSync(fd));
    checkNamedOpened(io, fd, file, fileIdentity, 0);
    fsyncDirectory(io, parent.directory);
    verify();
  } catch {
    failureCause = 'SIDECAR_CREATE_UNCONFIRMED';
    state = 'COMMIT_UNCERTAIN'; reason = failureCause;
    closeOwned(failureCause);
    fail(failureCause);
  }
  async function retain(raw) {
    if (state !== 'OPEN' || busy || finalSeen) fail('SIDECAR_NOT_WRITABLE');
    busy = true;
    let writeAttempted = false;
    try {
      // The codec snapshots and validates the producer. Only its validated
      // record is inspected here; raw objects are never trusted for ordering.
      const encoded = encodeArmSidecarRecordV1(raw, ordinal, previousSha256);
      const event = encoded.record;
      if (ordinal === 0 && (event.kind !== 'HEADER' || previousSha256 !== null)) fail('SIDECAR_HEADER');
      if (ordinal > 0 && event.kind === 'HEADER') fail('SIDECAR_HEADER');
      if (finalSeen || (event.kind === 'FINAL' && ordinal === 0)) fail('SIDECAR_FINAL_ORDER');
      if (encoded.bytes.length > SIDECAR_LIMITS.maxRecordBytes ||
          byteLength + encoded.bytes.length > SIDECAR_LIMITS.maxBytes ||
          ordinal >= SIDECAR_LIMITS.maxRecords) fail('SIDECAR_CAPACITY');
      verify();
      let offset = 0;
      while (offset < encoded.bytes.length) {
        writeAttempted = true;
        const written = io.writeSync(fd, encoded.bytes, offset, encoded.bytes.length - offset, null);
        if (!Number.isSafeInteger(written) || written <= 0 || written > encoded.bytes.length - offset) fail('SIDECAR_WRITE');
        offset += written;
      }
      io.fsyncSync(fd);
      const found = readExact(io, fd, encoded.bytes.length, byteLength);
      if (!found.equals(encoded.bytes)) fail('SIDECAR_READBACK');
      const nextSize = byteLength + encoded.bytes.length;
      checkNamedOpened(io, fd, file, fileIdentity, nextSize);
      recheckExternalDemoStateV1(parent, SOURCE_ROOT);
      checkPrivateDirectory(parent);
      if (event.kind === 'FINAL') {
        closeOwned('SIDECAR_CLOSE_UNCONFIRMED');
        if (state !== 'OPEN') fail('SIDECAR_CLOSE_UNCONFIRMED');
      }
      // An operation is acknowledged only after every check and final close.
      byteLength = nextSize;
      previousSha256 = encoded.sha256;
      ordinal += 1;
      finalSeen = event.kind === 'FINAL';
      if (finalSeen) state = 'CLOSED';
    } catch {
      failureCause ??= writeAttempted ? 'SIDECAR_COMMIT_UNCONFIRMED' : 'SIDECAR_PREWRITE_REFUSED';
      reason = writeAttempted ? 'SIDECAR_COMMIT_UNCONFIRMED' : 'SIDECAR_PREWRITE_REFUSED';
      state = writeAttempted ? 'COMMIT_UNCERTAIN' : 'FAILED';
      closeOwned(failureCause);
      fail(reason);
    } finally { busy = false; }
  }
  function close() {
    if (busy) fail('SIDECAR_BUSY');
    if (state === 'OPEN') {
      try { verify(); } catch { failureCause ??= 'SIDECAR_FILE_CHANGED'; state = 'COMMIT_UNCERTAIN'; reason = 'SIDECAR_FILE_CHANGED'; }
      closeOwned('SIDECAR_CLOSE_UNCONFIRMED');
      if (state === 'OPEN') state = 'CLOSED';
    }
    return snapshot({ file, state, reason, failureCause, ordinal, byteLength, previousSha256, finalSeen });
  }
  return Object.freeze({ retain, inspect: () => snapshot({ file, state, reason, failureCause, ordinal, byteLength, previousSha256, finalSeen }), close });
}

function readableDirectory(value) {
  if (typeof value !== 'string' || !value.length || value.length > 4096 || value.includes('\0') || !path.isAbsolute(value)) fail('SIDECAR_DIRECTORY_INVALID');
  const named = fs.lstatSync(path.resolve(value));
  if (!named.isDirectory() || named.isSymbolicLink()) fail('SIDECAR_DIRECTORY_INVALID');
  const directory = fs.realpathSync(value);
  const source = fs.realpathSync(SOURCE_ROOT);
  const stat = fs.lstatSync(directory);
  const relative = path.relative(source, directory);
  const nested = relative === '' || (!relative.startsWith('..' + path.sep) && relative !== '..' && !path.isAbsolute(relative));
  const reverse = path.relative(directory, source);
  const containsSource = reverse === '' || (!reverse.startsWith('..' + path.sep) && reverse !== '..' && !path.isAbsolute(reverse));
  const uid = currentUid();
  if (!stat.isDirectory() || stat.isSymbolicLink() || nested || containsSource || (stat.mode & 0o077) || (uid !== null && stat.uid !== uid)) fail('SIDECAR_DIRECTORY_INVALID');
  fs.accessSync(directory, fs.constants.R_OK | fs.constants.X_OK);
  return { directory, ...identity(stat) };
}

export function inspectPairedArmSidecarStoreV1(input) {
  let fd = null;
  try {
    const { directory } = record(input, ['directory']);
    const selected = readableDirectory(directory), file = path.join(selected.directory, NAME);
    let named;
    try { named = fs.lstatSync(file); } catch { return cloneFreeze({ schemaVersion: 'nisi-paired-arm-sidecar-inspection-v1', status: 'UNAVAILABLE', records: [], verifiedPrefixBytes: 0, lastSha256: null, authorizing: false, resumable: false, pastAcknowledgement: 'UNKNOWN' }); }
    if (!named.isFile() || named.isSymbolicLink() || named.nlink !== 1 || (named.mode & 0o077) || (currentUid() !== null && named.uid !== currentUid()) || named.size > SIDECAR_LIMITS.maxBytes) fail('SIDECAR_READ');
    fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NONBLOCK | noFollow);
    const opened = fs.fstatSync(fd);
    if (!opened.isFile() || !sameIdentity(identity(named), opened) || opened.size !== named.size || opened.size > SIDECAR_LIMITS.maxBytes) fail('SIDECAR_READ');
    const bytes = readExact(fs, fd, opened.size);
    const afterDirectory = readableDirectory(selected.directory);
    const after = fs.lstatSync(file), last = fs.fstatSync(fd);
    if (!sameIdentity(identity(named), after) || !sameIdentity(identity(named), last) || after.size !== named.size || last.size !== opened.size ||
        after.mtimeMs !== named.mtimeMs || after.ctimeMs !== named.ctimeMs || last.mtimeMs !== opened.mtimeMs || last.ctimeMs !== opened.ctimeMs ||
        afterDirectory.dev !== selected.dev || afterDirectory.ino !== selected.ino) fail('SIDECAR_READ');
    const owned = fd; fd = null; fs.closeSync(owned);
    let at = 0, ordinal = 0, previous = null, finalSeen = false, status = bytes.length ? 'INCOMPLETE' : 'EMPTY', records = [];
    while (at < bytes.length) {
      const end = bytes.indexOf(10, at);
      if (end < 0) { status = 'PARTIAL_TAIL'; break; }
      try {
        const decoded = decodeArmSidecarRecordV1(bytes.subarray(at, end + 1), ordinal, previous);
        if (finalSeen) fail('SIDECAR_ORDER');
        records.push({ record: decoded.record, sha256: decoded.sha256, ordinal });
        previous = decoded.sha256; ordinal += 1; finalSeen = decoded.record.kind === 'FINAL'; at = end + 1;
        status = finalSeen ? 'FINAL_PRESENT' : 'INCOMPLETE';
      } catch { status = 'CORRUPT'; break; }
    }
    return cloneFreeze({ schemaVersion: 'nisi-paired-arm-sidecar-inspection-v1', status, records, verifiedPrefixBytes: at, lastSha256: previous, authorizing: false, resumable: false, pastAcknowledgement: 'UNKNOWN' });
  } catch {
    if (fd !== null) try { fs.closeSync(fd); } catch { /* unavailable */ }
    return cloneFreeze({ schemaVersion: 'nisi-paired-arm-sidecar-inspection-v1', status: 'UNAVAILABLE', records: [], verifiedPrefixBytes: 0, lastSha256: null, authorizing: false, resumable: false, pastAcknowledgement: 'UNKNOWN' });
  }
}

// PRIVATE, read-only cross-ledger observations. No replay, owner reconstruction,
// dispatch inference, authenticated provenance or measured effectiveness.
import {cloneFreeze,stableStringify} from '../workflow/contracts.mjs';
import {record} from '../evaluation/intake-v1.mjs';
import {encodeTrialEventV1} from './paired-trial-event-codec-v1.mjs';
import {inspectPairedTrialEventStoreV1} from './paired-trial-event-store-v1.mjs';
import {reconcileTrialRetentionEventsV1} from './paired-trial-reconciliation-v1.mjs';
import {inspectPairedArmSidecarStoreV1} from './paired-arm-sidecar-store-v1.mjs';
import {armSidecarDigestV1} from './paired-arm-sidecar-codec-v1.mjs';

const same=(a,b)=>stableStringify(a)===stableStringify(b);
const requireThat=ok=>{if(!ok)throw Error('ARM_CROSS_LINK_INVALID');};
const flags={authorizing:false,resumable:false,actualDispatchCount:null,
  measurementVerified:false,causalClaim:false,promotionEligible:false,
  sourceTrust:'UNAUTHENTICATED_LOCAL_BYTES',pastAcknowledgement:'UNKNOWN',
  remoteExecutionStopped:'UNKNOWN',candidateBytesRevalidated:false};
function stateOf(row){
  for(const phase of ['ORACLE','EXECUTOR']){
    if(row.observed[phase])return phase==='ORACLE'?'COMPLETE':'EXECUTOR_OBSERVED';
    if(row.started[phase])return 'STARTED_INCOMPLETE';
    if(row.prepared[phase])return 'PREPARED_UNCONFIRMED';
  }
  return 'NOT_STARTED';
}
function inspectCaptured(main,side){
  const base={schemaVersion:'nisi-paired-arm-reconciliation-v1',
    mainByteStatus:main.status,sidecarByteStatus:side.status,...flags};
  const result=(status,reason,rows=[],missing=[])=>cloneFreeze({...base,status,reason,rows,missing});
  if([main.status,side.status].some(s=>['CORRUPT','UNAVAILABLE'].includes(s)))
    return result('REFUSED','UNAVAILABLE_OR_CORRUPT_BYTES');
  if(main.events.length===0)return result('INCOMPLETE','NO_MAIN_SCHEDULE');
  const semantic=reconcileTrialRetentionEventsV1({events:main.events,byteStatus:main.status});
  if(semantic.status==='REFUSED')return result('REFUSED','MAIN_SEMANTICS_REFUSED');
  const schedule=main.events[0];
  const rows=schedule.intents.map(intent=>({intent,ownerSetId:null,prepared:{},started:{},observed:{},history:null}));
  const byRequest=new Map(rows.map(row=>[row.intent.requestId,row]));
  let previous=null;
  const events=main.events.map((event,index)=>{
    const encoded=encodeTrialEventV1(event,index,previous);previous=encoded.sha256;
    return {event,sha256:encoded.sha256,index};
  });
  const bySequence=new Map(events.map(x=>[x.event.sequence,x]));
  const owners=new Map(),covered=new Set();let lastMain=0,final=false;
  function custody(value,intent,prepared){
    for(const k of ['taskSha256','baselineSha256','oracleSha256','toolchainSha256','resourceBudgetSha256'])
      requireThat(value[k]===intent[k]);
    if(prepared)for(const k of ['suiteFingerprint','reviewedSourceFingerprint'])
      requireThat(value[k]===prepared.record.observation.custody[k]);
  }
  function nextPreparation(at){
    const head=events[at].event;
    if(head.type==='SCHEDULE')return {requestId:rows[0].intent.requestId,phase:'EXECUTOR'};
    if(head.type!=='PHASE_RESULT')return null;
    if(head.phase==='EXECUTOR')return {requestId:head.requestId,phase:'ORACLE'};
    const next=rows[rows.findIndex(r=>r.intent.requestId===head.requestId)+1];
    return next?{requestId:next.intent.requestId,phase:'EXECUTOR'}:null;
  }
  try{
    for(const [ordinal,entry] of side.records.entries()){
      const r=entry.record,ref=bySequence.get(r.main.sequence);
      requireThat(!final&&ref&&ref.sha256===r.main.sha256&&ref.index>=lastMain);
      lastMain=ref.index;
      if(ordinal===0){
        requireThat(r.kind==='HEADER'&&ref.index===0&&r.runnerId===schedule.runnerId&&
          r.planSha256===schedule.plan.planSha256&&r.profileSha256===schedule.profile.profileSha256&&
          r.intentsSha256===armSidecarDigestV1(schedule.intents));continue;
      }
      requireThat(r.kind!=='HEADER');
      if(r.kind==='FINAL'){
        requireThat(ref.event.type==='FINAL'&&same(r.rows,rows.map(row=>({requestId:row.intent.requestId,state:stateOf(row)}))));
        final=true;continue;
      }
      const row=byRequest.get(r.requestId);requireThat(row);
      if(row.ownerSetId===null){
        requireThat(r.kind==='PREPARED'&&!owners.has(r.ownerSetId));
        row.ownerSetId=r.ownerSetId;owners.set(r.ownerSetId,r.requestId);
      }
      requireThat(r.ownerSetId===row.ownerSetId);
      if(r.kind==='PREPARED'){
        const expected=nextPreparation(ref.index);
        requireThat(expected&&expected.requestId===r.requestId&&expected.phase===r.phase&&!row.prepared[r.phase]);
        requireThat(r.intentSha256===armSidecarDigestV1(row.intent)&&
          r.approval.planSha256===row.intent.planSha256&&r.approval.profileSha256===row.intent.profileSha256);
        if(r.phase==='ORACLE')requireThat(row.observed.EXECUTOR&&
          same(r.approval,row.prepared.EXECUTOR.record.approval)&&r.inputsSha256===row.prepared.EXECUTOR.record.inputsSha256&&
          r.observedAtMs>=row.history.record.entries.at(-1).observedAtMs);
        custody(r.observation.custody,row.intent,row.prepared.EXECUTOR);
        row.prepared[r.phase]=entry;
      }else if(r.kind==='START_LINKED'){
        const prepared=row.prepared[r.phase];
        requireThat(prepared&&!row.started[r.phase]&&r.preparedSha256===prepared.sha256&&
          ref.event.type==='START_INTENT'&&ref.event.requestId===r.requestId&&ref.event.phase===r.phase&&
          bySequence.get(prepared.record.main.sequence).index===ref.index-1);
        row.started[r.phase]=entry;covered.add(ref.event.sequence);
      }else if(r.kind==='HISTORY'){
        requireThat(r.intentSha256===armSidecarDigestV1(row.intent)&&same(r.approval,row.prepared.EXECUTOR.record.approval));
        const old=row.history?.record.entries??[];
        requireThat(r.entries.length>old.length&&same(r.entries.slice(0,old.length),old));
        let at=row.prepared.EXECUTOR.record.observedAtMs;
        for(const [index,observation] of r.entries.entries()){
          const phase=index<2?'EXECUTOR':'ORACLE',point=index%2?'CONSUMPTION_RECHECK_PASSED':'PERMIT_MINTED';
          const started=row.started[phase],prepared=row.prepared[phase];
          requireThat(started&&prepared&&observation.phase===phase&&observation.point===point&&
            observation.generation===started.record.main.sequence&&observation.observedAtMs>=at&&
            observation.observedAtMs>=prepared.record.observedAtMs);
          custody(observation.observation.custody,row.intent,prepared);at=observation.observedAtMs;
        }
        const latestPhase=r.entries.length<=2?'EXECUTOR':'ORACLE';
        requireThat(ref.event.type==='START_INTENT'&&ref.event.requestId===r.requestId&&ref.event.phase===latestPhase);
        row.history=entry;
      }else if(r.kind==='PHASE_OBSERVED'){
        const started=row.started[r.phase],prepared=row.prepared[r.phase],history=row.history;
        requireThat(started&&prepared&&history&&!row.observed[r.phase]&&r.startSha256===started.sha256&&r.historySha256===history.sha256&&
          ref.event.type==='PHASE_RESULT'&&ref.event.phase===r.phase&&ref.event.requestId===r.requestId&&
          bySequence.get(history.record.main.sequence).index===ref.index-1&&history.record.disposition==='POST_PHASE_LOCAL_OBSERVATIONS'&&
          history.record.entries.length===(r.phase==='EXECUTOR'?2:4));
        if(r.phase==='EXECUTOR'){
          const p=r.projection,e=ref.event.result;
          requireThat(p.intentSha256===prepared.record.intentSha256&&p.inputsSha256===prepared.record.inputsSha256&&
            p.candidate.candidateSha256===e.candidateSha256&&p.completionClaim===e.completionClaim&&
            same(p.usage.projectedTokens,e.tokenUsage)&&p.usage.projectedModelCalls===e.modelCalls&&p.usage.durationMs===e.durationMs&&
            p.treatment.arm===row.intent.arm&&p.treatment.policySha256===schedule.profile.trialPolicy.sha256);
        }else requireThat(row.observed.EXECUTOR&&ref.event.result.oracleCandidateSha256===row.observed.EXECUTOR.record.projection.candidate.candidateSha256);
        row.observed[r.phase]=entry;covered.add(ref.event.sequence);
      }else requireThat(false);
    }
    const missing=events.filter(x=>['START_INTENT','PHASE_RESULT'].includes(x.event.type)&&!covered.has(x.event.sequence))
      .map(x=>({sequence:x.event.sequence,requestId:x.event.requestId,phase:x.event.phase,
        missing:x.event.type==='START_INTENT'?'START_LINKED':'PHASE_OBSERVED'}));
    if(final)requireThat(missing.length===0);
    const observed=rows.map(row=>({requestId:row.intent.requestId,ownerSetId:row.ownerSetId,state:stateOf(row)}));
    const complete=final&&main.status==='FINAL_PRESENT'&&side.status==='FINAL_PRESENT';
    return result(complete?'FINAL_CROSSLINKED':'INCOMPLETE',complete?null:
      missing.length?'MISSING_SIDECAR_LINKS':side.records.length===0?'NO_SIDECAR_HEADER':'UNFINISHED_OR_PARTIAL_PREFIX',observed,missing);
  }catch{return result('REFUSED','CROSS_LEDGER_BINDING_OR_ORDER');}
}

export function inspectPairedArmTrialV1(input){
  try{
    const {directory}=record(input,['directory']);
    // Each file is captured once. No atomic two-file snapshot or hostile-writer
    // isolation is asserted; an actively changing pair can be incomplete/refused.
    const main=inspectPairedTrialEventStoreV1({directory});
    const sidecar=inspectPairedArmSidecarStoreV1({directory});
    return inspectCaptured(main,sidecar);
  }catch{return cloneFreeze({schemaVersion:'nisi-paired-arm-reconciliation-v1',status:'REFUSED',
    reason:'INSPECTION_UNAVAILABLE',rows:[],missing:[],...flags});}
}

// PRIVATE composition of the original arm controller and both evidence stores.
// Caller still supplies trusted, admitted observation/reservation callbacks.
// This is not a CLI, model picker, signal handler, scheduler, or resume API.
import fs from 'node:fs';
import {record} from '../../evaluation/intake-v1.mjs';
import {cloneFreeze} from '../../workflow/contracts.mjs';
import {createPairedTrialRunnerV1} from '../../evaluation/paired-trial-runner-v1.mjs';
import {createRepositoryPairedArmOwnerV1} from './paired-trial-arm-owner-v1.mjs';
import {createPairedTrialEventStoreV1} from '../../history/paired-trial-event-store-v1.mjs';
import {createPairedArmSidecarStoreV1} from '../../history/paired-arm-sidecar-store-v1.mjs';
import {armSidecarDigestV1,projectArmAdmissionV1,projectArmProjectionV1} from '../../history/paired-arm-sidecar-codec-v1.mjs';

const fail=()=>{throw Object.assign(Error('RUNNER_ARM_STORAGE_UNCONFIRMED'),{code:'RUNNER_ARM_STORAGE_UNCONFIRMED'});};
const ioKeys=['openSync','closeSync','writeSync','readSync','fstatSync','fsyncSync'];
const captureIo=io=>Object.fromEntries(ioKeys.map(key=>{
  const fn=Object.getOwnPropertyDescriptor(io,key)?.value;if(typeof fn!=='function')fail();return [key,fn.bind(io)];
}));
export function createDurablePairedArmOwnerV1(input,dependencies={mainIo:fs,sidecarIo:fs}){
  const top=record(input,['plan','profile','approval','now','observe','reserve','parentDirectory']);
  const deps=record(dependencies,['mainIo','sidecarIo']);
  const mainIo=captureIo(deps.mainIo),sidecarIo=captureIo(deps.sidecarIo);
  // Both the controller and history projection consume this one owned snapshot.
  // Never reread the caller-owned object after trusted callbacks have run.
  const approved=cloneFreeze(top.approval);
  let main=null,sidecar=null,head=null,schedule=null,state='READY',failure=null,pending=0,ledger=null;
  let cleanup='NOT_OPENED',report=null;
  const rows=new Map();
  const healthy=()=>{if(failure||!main||!sidecar)fail();};
  const rowState=row=>{
    for(const phase of ['ORACLE','EXECUTOR']){
      if(row?.observed[phase])return phase==='ORACLE'?'COMPLETE':'EXECUTOR_OBSERVED';
      if(row?.starts[phase])return 'STARTED_INCOMPLETE';
      if(row?.prepared[phase])return 'PREPARED_UNCONFIRMED';
    }
    return 'NOT_STARTED';
  };
  async function sideWrite(value){
    await sidecar.retain(value);
    return {record:value,sha256:sidecar.inspect().lastSha256};
  }
  async function guarded(fn){
    pending++;
    try{healthy();return await fn();}catch{failure??='RUNNER_ARM_STORAGE_UNCONFIRMED';fail();}
    finally{pending--;}
  }
  const arm=createRepositoryPairedArmOwnerV1({plan:top.plan,profile:top.profile,approval:approved,
    now:top.now,observe:top.observe,reserve:top.reserve,
    retainAdmission:raw=>guarded(async()=>{
      if(!head)fail();
      // The converter snapshots the original typed producer before field access.
      // Approval is immutable and was validated by the arm-controller constructor.
      const value=projectArmAdmissionV1(raw,head,approved);
      let row=rows.get(value.requestId);
      if(!row){
        if(value.kind!=='PREPARED')fail();
        row={ownerSetId:value.ownerSetId,prepared:{},starts:{},observed:{},history:null};rows.set(value.requestId,row);
      }
      if(value.ownerSetId!==row.ownerSetId)fail();
      const entry=await sideWrite(value);
      if(value.kind==='PREPARED')row.prepared[value.phase]=entry;
      else row.history=entry;
    }),
    retain:event=>guarded(async()=>{
      await main.retain(event);
      head=Object.freeze({sequence:event.sequence,sha256:main.inspect().lastSha256});
      if(event.type==='SCHEDULE'){
        schedule=event;
        await sideWrite({kind:'HEADER',main:head,runnerId:event.runnerId,planSha256:event.plan.planSha256,
          profileSha256:event.profile.profileSha256,intentsSha256:armSidecarDigestV1(event.intents)});
      }else if(event.type==='FINAL'){
        await sideWrite({kind:'FINAL',main:head,failure:arm.inspect().failure,
          rows:schedule.intents.map(intent=>({requestId:intent.requestId,state:rowState(rows.get(intent.requestId))}))});
      }else{
        const row=rows.get(event.requestId);if(!row)fail();
        const common={main:head,requestId:event.requestId,ownerSetId:row.ownerSetId,phase:event.phase};
        if(event.type==='START_INTENT'){
          const prepared=row.prepared[event.phase];if(!prepared)fail();
          row.starts[event.phase]=await sideWrite({kind:'START_LINKED',...common,preparedSha256:prepared.sha256});
        }else{
          const started=row.starts[event.phase];if(!started||!row.history)fail();
          const source=arm.inspect().rows.find(r=>r.requestId===event.requestId);
          const projection=event.phase==='EXECUTOR'?projectArmProjectionV1(source.projection):null;
          row.observed[event.phase]=await sideWrite({kind:'PHASE_OBSERVED',...common,
            startSha256:started.sha256,historySha256:row.history.sha256,projection});
        }
      }
    })});
  const runner=createPairedTrialRunnerV1({plan:top.plan,profile:top.profile,host:arm.host});
  // This version's declared bounded sidecar supports at most 256 scheduled arms.
  // Validate before any directory allocation rather than failing after dispatch.
  if(top.plan.tasks.length*top.plan.repetitions*2>256)fail();
  function inspect(){
    return report??cloneFreeze({schemaVersion:'nisi-durable-paired-arm-owner-v1',state,failure,cleanup,pendingRetentions:pending,
      main:main?.inspect()??null,sidecar:sidecar?.inspect()??null,
      runner:ledger?{stopReason:ledger.stopReason,counts:ledger.counts,retentionStatus:ledger.retentionStatus}:null,
      recorded:false,authorizing:false,resumable:false,actualDispatchCount:null,
      measurementVerified:false,causalClaim:false,promotionEligible:false});
  }
  async function run(...args){
    if(args.length||state!=='READY')fail();state='RUNNING';
    try{
      main=createPairedTrialEventStoreV1({parentDirectory:top.parentDirectory},{io:mainIo});
      sidecar=createPairedArmSidecarStoreV1({directory:main.inspect().directory},{io:sidecarIo});
      ledger=await runner.run();
    }catch{failure??='RUNNER_ARM_STORAGE_UNCONFIRMED';}
    finally{
      cleanup=pending?'DEFERRED_PENDING_RETENTION':'CLOSED';
      if(!pending)for(const store of [sidecar,main])if(store){
        try{if(store.close().state!=='CLOSED')cleanup='UNCONFIRMED';}catch{cleanup='UNCONFIRMED';}
      }
      state='FINISHED';
    }
    const view=inspect();
    report=cloneFreeze({...view,recorded:!failure&&cleanup==='CLOSED'&&view.main?.finalSeen===true&&
      view.sidecar?.finalSeen===true&&ledger?.retentionStatus==='CONFIRMED'});
    return report;
  }
  return Object.freeze({run,inspect,requestStop:(...args)=>{
    if(args.length)fail();return runner.requestStop();
  }});
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { pairedArmContext } from './helpers/paired-arm-owner-fixture.mjs';
import {
  armSidecarDigestV1,
  projectArmAdmissionV1,
  projectArmProjectionV1,
  readArmSidecarRecordV1,
  encodeArmSidecarRecordV1,
  decodeArmSidecarRecordV1,
} from '../history/paired-arm-sidecar-codec-v1.mjs';
import { stableStringify, sha256Text } from '../workflow/contracts.mjs';

const D = '0'.repeat(64);
const clone = value => JSON.parse(JSON.stringify(value));
const invalid = fn => assert.throws(fn, { code: 'ARM_SIDECAR_INVALID' });
const fingerprint = (domain, value) => {
  const body = clone(value);
  delete body.fingerprint;
  body.fingerprint = sha256Text(domain + '\0' + stableStringify(body));
  return body;
};
const admissionFingerprint = value => fingerprint('nisi/scheduled-arm-admission/v1', value);
const projectionFingerprint = value => fingerprint('nisi/repository-trial-projection/v2', value);
const main = sequence => ({ sequence, sha256: sha256Text('test/main-event\0' + sequence) });

test('sidecar codec accepts only original arm-owner producer shapes and round-trips its chain', async t => {
  const c = await pairedArmContext(t);
  const ledger = await c.runner.run();
  assert.equal(ledger.counts.completed, 1);

  const preparedRaw = c.state.admissions.find(row =>
    row.schemaVersion === 'nisi-scheduled-arm-admission-v1' && row.phase === 'EXECUTOR');
  const historyRaw = c.state.admissions.find(row =>
    row.schemaVersion === 'nisi-scheduled-arm-admission-history-v1' &&
    row.disposition === 'POST_PHASE_LOCAL_OBSERVATIONS');
  const view = c.owner.inspect();
  const projectionRaw = view.rows[0].projection;
  assert(preparedRaw); assert(historyRaw); assert(projectionRaw);

  const prepared = projectArmAdmissionV1(preparedRaw, main(1));
  const history = projectArmAdmissionV1(historyRaw, main(2), c.approval);
  const projection = projectArmProjectionV1(projectionRaw);
  assert.equal(prepared.kind, 'PREPARED');
  assert.equal(prepared.phase, 'EXECUTOR');
  assert.equal(prepared.producerFingerprint, preparedRaw.fingerprint);
  assert.equal(prepared.intentSha256, armSidecarDigestV1(preparedRaw.intent));
  assert.equal(history.kind, 'HISTORY');
  assert.equal(history.producerFingerprint, historyRaw.fingerprint);
  assert.equal(history.entries.length, 2);
  assert.equal(projection.fingerprint, projectionRaw.fingerprint);
  assert.equal(projection.candidate.candidateSha256, projectionRaw.candidate.candidateSha256);
  assert.equal(Object.hasOwn(projection, 'intent'), false);
  assert.equal(Object.hasOwn(projection, 'inputs'), false);
  assert.equal(stableStringify(projection).includes('candidateText'), false);

  const header = readArmSidecarRecordV1({ kind: 'HEADER', main: main(0),
    runnerId: view.runnerId, planSha256: c.plan.planSha256,
    profileSha256: c.profile.profileSha256,
    intentsSha256: armSidecarDigestV1(c.state.events[0].intents) });
  const encodedHeader = encodeArmSidecarRecordV1(header, 0, null);
  const encodedPrepared = encodeArmSidecarRecordV1(prepared, 1, encodedHeader.sha256);
  assert.deepEqual(decodeArmSidecarRecordV1(encodedHeader.bytes, 0, null), encodedHeader);
  assert.deepEqual(decodeArmSidecarRecordV1(
    encodedPrepared.bytes, 1, encodedHeader.sha256), encodedPrepared);

  const corrupted = Buffer.from(encodedPrepared.bytes);
  const at = corrupted.indexOf(Buffer.from(encodedPrepared.sha256));
  assert(at >= 0); corrupted[at] = corrupted[at] === 0x30 ? 0x31 : 0x30;
  invalid(() => decodeArmSidecarRecordV1(corrupted, 1, encodedHeader.sha256));
  invalid(() => decodeArmSidecarRecordV1(encodedPrepared.bytes, 1, D));

  await t.test('closed original admission and history schemas reject recomputed hybrids', () => {
    const admissionExtra = clone(preparedRaw);
    admissionExtra.unreviewed = false;
    invalid(() => projectArmAdmissionV1(admissionFingerprint(admissionExtra), main(1)));

    const historyHybrid = clone(historyRaw);
    historyHybrid.phase = 'EXECUTOR';
    historyHybrid.observation = preparedRaw.observation;
    invalid(() => projectArmAdmissionV1(admissionFingerprint(historyHybrid), main(2), c.approval));

    const historyMissing = clone(historyRaw);
    delete historyMissing.sourceTrust;
    invalid(() => projectArmAdmissionV1(admissionFingerprint(historyMissing), main(2), c.approval));
  });

  await t.test('closed V2 producer rejects omitted discarded data and unknown data', () => {
    const omitted = clone(projectionRaw);
    delete omitted.repositoryReceiptReasons;
    invalid(() => projectArmProjectionV1(projectionFingerprint(omitted)));

    const extra = clone(projectionRaw);
    extra.unreviewedProviderDetail = 'not retained';
    invalid(() => projectArmProjectionV1(projectionFingerprint(extra)));
  });

  await t.test('terminal labels are non-null and from the current producer contracts', () => {
    for (const key of ['repositoryReceiptStatus', 'engineOutcome', 'workflowOutcome']) {
      const missing = clone(projectionRaw);
      missing[key] = null;
      invalid(() => projectArmProjectionV1(projectionFingerprint(missing)));
      const unknown = clone(projectionRaw);
      unknown[key] = 'UNKNOWN_FUTURE_LABEL';
      invalid(() => projectArmProjectionV1(projectionFingerprint(unknown)));
    }
  });

  await t.test('proxy and getter inputs refuse without invoking traps', () => {
    let traps = 0;
    const proxy = new Proxy(preparedRaw, {
      get() { traps++; throw new Error('get trap'); },
      ownKeys() { traps++; throw new Error('ownKeys trap'); },
      getOwnPropertyDescriptor() { traps++; throw new Error('descriptor trap'); },
    });
    invalid(() => projectArmAdmissionV1(proxy, main(1)));
    assert.equal(traps, 0);

    const revoked = Proxy.revocable(preparedRaw, {});
    revoked.revoke();
    invalid(() => projectArmAdmissionV1(revoked.proxy, main(1)));
